:root {
  --bg: #060a1a;
  --bg-2: #0b1230;
  --blue: #38d9ff;
  --blue-deep: #0f7dff;
  --orange: #ff8a3c;
  --orange-deep: #ff4d1f;
  --ink: #eaf3ff;
  --muted: #8fa2c9;
  --panel: rgba(10, 16, 38, 0.88);
  --line: rgba(133, 180, 255, 0.18);
  --font-ui: "Space Grotesk", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-display: "Chakra Petch", "Space Grotesk", system-ui, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
}

body {
  background:
    radial-gradient(1200px 700px at 12% -10%, rgba(24, 74, 160, 0.45), transparent 62%),
    radial-gradient(1100px 640px at 92% 0%, rgba(160, 62, 24, 0.32), transparent 60%),
    radial-gradient(900px 600px at 50% 120%, rgba(38, 24, 96, 0.5), transparent 65%),
    linear-gradient(180deg, #070b1c 0%, #050815 100%);
  color: var(--ink);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  touch-action: none;
}

.app {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100dvh;
  min-height: 100svh;
  gap: 6px;
  padding:
    max(8px, env(safe-area-inset-top))
    max(12px, env(safe-area-inset-right))
    max(8px, env(safe-area-inset-bottom))
    max(12px, env(safe-area-inset-left));
}

/* ---------- scoreboard ---------- */
.hud {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  max-width: 1420px;
  width: 100%;
  margin: 0 auto;
  padding: 2px 4px 0;
}

.team {
  display: flex;
  align-items: center;
  gap: 10px;
}

.team-orange { justify-content: flex-end; }

.team-chip {
  position: relative;
  width: 42px;
  height: 42px;
  border-radius: 13px;
