.tbtn.boost.on { background: linear-gradient(180deg, rgba(255, 200, 80, 0.66), rgba(190, 110, 20, 0.7)); box-shadow: 0 0 30px rgba(255, 190, 70, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.2); }
