}

.pause-btn span { width: 4px; height: 13px; border-radius: 2px; background: currentColor; }

/* ---------- footer ---------- */
.foot {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  max-width: 1420px;
  width: 100%;
  margin: 0 auto;
  padding: 4px 4px 0;
}

.boost-meter {
