  align-items: center;
  gap: 9px;
  width: min(260px, 40vw);
}

.boost-label {
  font-size: 9px;
  letter-spacing: 0.24em;
  font-weight: 700;
  color: #8ea3ca;
}

.boost-track {
  position: relative;
  flex: 1;
  height: 10px;
  border-radius: 6px;
  overflow: hidden;
  background: rgba(10, 18, 40, 0.9);
  border: 1px solid rgba(140, 180, 255, 0.2);
  box-shadow: inset 0 1px 4px rgba(0, 0, 0, 0.6);
}

.boost-track i {
  display: block;
  height: 100%;
  width: 50%;
  border-radius: 5px;
  background: linear-gradient(90deg, #ffd76a, #ff9a3c 55%, #ff6a2f);
