  pointer-events: none;
}

.boost-num {
  width: 24px;
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 700;
  color: #ffcf8a;
  font-variant-numeric: tabular-nums;
}

.foot-hint {
  margin: 0;
  font-size: 10.5px;
  letter-spacing: 0.04em;
  color: #7d8fb4;
  text-align: center;
  flex: 1 1 auto;
}

.foot-hint kbd { min-width: 18px; height: 18px; font-size: 8px; vertical-align: middle; }

@media (max-height: 560px), (max-width: 720px) {
  .hud { padding-top: 0; }
  .team-chip { width: 32px; height: 32px; border-radius: 10px; }
  .team-chip i { width: 12px; height: 12px; }
  .team-copy span { font-size: 9px; }
  .clock { min-width: 92px; padding: 3px 12px 4px; }
  .foot { padding-bottom: 2px; }
  .legend { grid-template-columns: repeat(2, 1fr); row-gap: 14px; }
