}

@media (max-height: 460px) {
  .tagline { display: none; }
  .legend { margin-top: 14px; padding-top: 12px; }
  .foot-hint { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .panel { animation: none; }
  .cta { transition: none; }
}

