function collideBallCar(car) {
  const cos = Math.cos(car.angle), sin = Math.sin(car.angle);
  const dx = ball.x - car.x, dy = ball.y - car.y;
  const lx = dx*cos + dy*sin;
  const ly = -dx*sin + dy*cos;
  const hw = car.w/2, hh = car.h/2;
  const qx = clamp(lx, -hw, hw), qy = clamp(ly, -hh, hh);
  let nx = lx - qx, ny = ly - qy;
  let d2 = nx*nx + ny*ny;
  if (d2 > ball.r*ball.r) return;
  let d = Math.sqrt(d2);
  if (d < 0.0001) {
    // ball center inside car: push up
    nx = 0; ny = -1; d = 0.0001;
  } else {
    nx /= d; ny /= d;
  }
  const wnx = nx*cos - ny*sin;
  const wny = nx*sin + ny*cos;
  const pen = ball.r - d;
  ball.x += wnx * (pen + 0.5);
  ball.y += wny * (pen + 0.5);
  const relx = ball.vx - car.vx, rely = ball.vy - car.vy;
  const rel = relx*wnx + rely*wny;
  if (rel < 0) {
    const impact = Math.min(1600, -rel);
    const j = impact * 0.92 + 60;
    ball.vx += wnx * j + car.vx * 0.32;
    ball.vy += wny * j + car.vy * 0.32;
    ball.spinV += (car.vx * 0.004) * (wnx >= 0 ? 1 : -1);
    if (car.hitCd <= 0) {
      car.hitCd = 0.06;
      const power = Math.min(1, impact/1100);
      audio.hit(power);
      game.shake = Math.max(game.shake, 4 + power*10);
      sparkBurst(ball.x - wnx*ball.r*0.6, ball.y - wny*ball.r*0.6, 6 + power*10, ...);
      // ball squash
      ball.squash = Math.min(0.5, 0.12 + power*0.35);
    }
    // clamp ball speed
    const sp = Math.hypot(ball.vx, ball.vy);
    if (sp > 1850) { ball.vx *= 1850/sp; ball.vy *= 1850/sp; }
  }
}
```
