let hexTile = null;
function buildHex() {
  const size = 34;
  const h = size * Math.sqrt(3);
  const c = document.createElement('canvas');
  c.width = size*3; c.height = h;
  const g = c.getContext('2d');
  g.strokeStyle = 'rgba(120,180,255,0.22)';
  g.lineWidth = 1.1;
  function hex(cx, cy) {
    g.beginPath();
    for (let i=0;i<6;i++) { const a = Math.PI/180*(60*i); const px = cx + Math.cos(a)*size*0.94, py = cy + Math.sin(a)*size*0.94; i?g.lineTo(px,py):g.moveTo(px,py); }
    g.closePath(); g.stroke();
  }
  // centers within tile for seamless-ish repetition
  hex(size, h/2);
  hex(size*3/2, 0);
  hex(size*3/2, h);
  return c; // use as pattern
}
