    scale = cw / viewW;
    viewH = ch / scale;
    if (viewH > H) { viewH = H; scale = ch / H; viewW = cw / scale; }
  } else {
    scale = Math.min(cw / W, ch / H);
    viewW = cw / scale;
    viewH = ch / scale;
  }
  view.scale = scale;
  view.viewW = viewW;
  view.viewH = viewH;
}
