      ctx.globalAlpha = 0.5;
      const ug = ctx.createRadialGradient(0, h / 2, 2, 0, h / 2, 70);
      ug.addColorStop(0, `rgba(${colRgb}, 0.65)`);
      ug.addColorStop(1, `rgba(${colRgb}, 0)`);
      ctx.fillStyle = ug;
